def comps(g):
 h=len(g);w=len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c] and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));cells=[]
    for y,x in q:
     cells.append((y,x))
     for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
      if 0<=yy<h and 0<=xx<w and g[yy][xx] and (yy,xx) not in seen:
       seen.add((yy,xx));q.append((yy,xx))
    out.append(cells)
 return sorted(out,key=lambda cells:min(c for r,c in cells))
